    // ---- [WSCoop] Luminary respec: right-click an allocated luminary to take it back (see WSLuminaryRespec) ----

    UFUNCTION(BlueprintOverride)
    FEventReply OnMouseButtonDown(FGeometry MyGeometry, FPointerEvent MouseEvent)
    {
        if (MouseEvent.GetEffectingButton() == EKeys::RightMouseButton)
            return FEventReply::Handled();
        return FEventReply::Unhandled();
    }

    UFUNCTION(BlueprintOverride)
    FEventReply OnMouseButtonUp(FGeometry MyGeometry, FPointerEvent MouseEvent)
    {
        if (MouseEvent.GetEffectingButton() != EKeys::RightMouseButton)
            return FEventReply::Unhandled();
        WSRequestRefund();
        return FEventReply::Handled();
    }

    void WSRequestRefund()
    {
        if (ProgressionComponent == nullptr || Unlock == nullptr)
            return;
        const FString Why = WSRefundBlockReason();
        if (Why == "-")
            return;
        if (!Why.IsEmpty())
        {
            WSCoop::ShowLocalNotice("Can't Take Back", Why);
            return;
        }
        WSLuminaryRespec::RequestRefund(ProgressionComponent, Unlock, InstanceData.FamiliarPassiveTag);
    }

    // How many of this luminary are allocated (familiar passives stack).
    int WSAllocatedCount()
    {
        if (ProgressionComponent == nullptr || Unlock == nullptr || Unlock.Type == EProgressionUnlockType::FamiliarAutoAttack)
            return 0;
        if (Unlock.Type == EProgressionUnlockType::FamiliarPassive)
        {
            InstanceData.UpdateStacksFromPassive(ItemStack);
            return InstanceData.CurrentStacks;
        }
        return IsUnlocked() ? 1 : 0;
    }

    // "" = may be taken back, "-" = nothing to take back, otherwise why not.
    FString WSRefundBlockReason()
    {
        if (WSAllocatedCount() <= 0)
            return "-";
        if (WSLuminaryRespec::IsSkillReward(Cast<APlayerCharacter>(ProgressionComponent.Owner), Unlock))
            return "This luminary was a free skill reward and can't be taken back.";
        if (ProgressionUnlockType::IsFamiliarUnlock(Unlock.Type))
        {
            if (!WSSpentPointRequirementsHoldWithout())
                return "Other luminaries need the points spent here. Take those back first.";
            return "";
        }
        TArray<UProgressionUnlockWidget> Neighbours = ToUnlockWidgets;
        Neighbours.Append(FromUnlockWidgets);
        for (UProgressionUnlockWidget Neighbour : Neighbours)
        {
            if (Neighbour == nullptr || Neighbour == this || Neighbour.WSAllocatedCount() <= 0)
                continue;
            // Only block when this luminary is what keeps that one connected.
            if (Neighbour.WSConnectionsHoldWithout(nullptr) && !Neighbour.WSConnectionsHoldWithout(this))
                return "Another luminary is connected through this one. Take that one back first.";
        }
        return "";
    }

    // The game's connection rule (CanAttemptUnlock) with Removed counted as not allocated.
    bool WSConnectionsHoldWithout(const UProgressionUnlockWidget Removed) const
    {
        for (const UProgressionUnlockWidget UnlockWidget : FromUnlockWidgets)
        {
            const bool bUnlocked = UnlockWidget != Removed && UnlockWidget.IsUnlocked();
            if (!bRequiresSingleConnection && !bUnlocked)
                return false;
            else if (bRequiresSingleConnection && bUnlocked)
                return true;
        }
        if (bIsOmnidirectional)
        {
            for (const UProgressionUnlockWidget UnlockWidget : ToUnlockWidgets)
            {
                const bool bUnlocked = UnlockWidget != Removed && UnlockWidget.IsUnlocked();
                if (!bRequiresSingleConnection && !bUnlocked)
                    return false;
                else if (bRequiresSingleConnection && bUnlocked)
                    return true;
            }
        }
        return true;
    }

    // Familiar luminaries need a number of points already spent: after taking one stack of this one back, the
    // others must still be allocatable in some order (cheapest requirement first).
    bool WSSpentPointRequirementsHoldWithout()
    {
        UPanelWidget Panel = GetParent();
        if (Panel == nullptr)
            return true;
        TArray<int> Entries; // requirement * 1000 + cost
        int NodeSpent = 0;
        for (UWidget Child : Panel.GetAllChildren())
        {
            UProgressionUnlockWidget Node = Cast<UProgressionUnlockWidget>(Child);
            if (Node == nullptr || Node.Unlock == nullptr || !ProgressionUnlockType::IsFamiliarUnlock(Node.Unlock.Type))
                continue;
            int Count = Node.WSAllocatedCount();
            if (Node == this)
                Count--;
            for (int i = 0; i < Count; i++)
            {
                Entries.Add(Node.InstanceData.RequiredSpentPoints * 1000 + Node.Unlock.Cost);
                NodeSpent += Node.Unlock.Cost;
            }
        }
        // Points spent outside these nodes count from the start.
        int Spent = Math::Max(ProgressionComponent.GetSpentTechnologyPoints() - Unlock.Cost - NodeSpent, 0);
        Entries.Sort();
        for (int Entry : Entries)
        {
            const int Required = Math::IntegerDivisionTrunc(Entry, 1000);
            if (Required > Spent)
                return false;
            Spent += Entry % 1000;
        }
        return true;
    }

    private void WSRefreshAfterRespec()
    {
        if (ProgressionComponent == nullptr || Unlock == nullptr)
            return;
        if (ProgressionUnlockType::IsFamiliarUnlock(Unlock.Type) && ItemStack != nullptr)
        {
            if (Unlock.Type == EProgressionUnlockType::FamiliarPassive)
            {
                InstanceData.UpdateStacksFromPassive(ItemStack);
                UpdateStateFromPassiveTag(ItemStack, InstanceData.FamiliarPassiveTag);
                return;
            }
            Text_Amount.SetText(FText::FromString(f"{(IsUnlocked() ? 1 : 0)}/{1}"));
            UpdateStateFromItem(ItemStack);
            return;
        }
        UpdateState();
    }
